import{_ as n,o as s,c as e,a0 as t}from"./chunks/framework.BEjAoB1x.js";const h=JSON.parse('{"title":"Ternary","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/ternary.md","filePath":"syntax/ternary.md"}'),i={name:"syntax/ternary.md"};function p(o,a,l,r,u,c){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="ternary" tabindex="-1">Ternary <a class="header-anchor" href="#ternary" aria-label="Permalink to &quot;Ternary&quot;">​</a></h1><p>Pemilihan nilai berdasarkan condition — tiga bentuk yang setara hasilnya, pilih sesuai keterbacaan.</p><h2 id="apa-yang-bisa-ditulis" tabindex="-1">Apa yang bisa ditulis? <a class="header-anchor" href="#apa-yang-bisa-ditulis" aria-label="Permalink to &quot;Apa yang bisa ditulis?&quot;">​</a></h2><p>Standard — <code>cond ? then : else</code>:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>label = score &gt;= 60 ? &quot;lulus&quot; : &quot;remedial&quot;</span></span></code></pre></div><p>Pipe — pasangan <code>condition | value</code> berantai:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nilai = score &gt;= 90 | &quot;A&quot; | score &gt;= 80 | &quot;B&quot; | &quot;C&quot;</span></span></code></pre></div><p>Cascade — pasangan <code>condition -&gt; value</code> berantai:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nilai = score &gt;= 90 -&gt; &quot;A&quot; | score &gt;= 80 -&gt; &quot;B&quot; | &quot;C&quot;</span></span></code></pre></div><p>Bentuk berantai dibaca dari kiri: condition pertama yang benar menentukan hasil; bagian terakhir tanpa condition adalah else.</p><h2 id="kapan-digunakan" tabindex="-1">Kapan digunakan? <a class="header-anchor" href="#kapan-digunakan" aria-label="Permalink to &quot;Kapan digunakan?&quot;">​</a></h2><p>Saat sebuah nilai punya dua kemungkinan atau lebih yang dipilih berdasarkan condition — tanpa menulis <code>if</code> penuh. Standard form untuk pilihan biner; pipe/cascade untuk pemilihan berjenjang.</p><h2 id="apa-hasilnya" tabindex="-1">Apa hasilnya? <a class="header-anchor" href="#apa-hasilnya" aria-label="Permalink to &quot;Apa hasilnya?&quot;">​</a></h2><p>Ternary adalah expression — menghasilkan nilai, bisa langsung dipakai di mana pun nilai dibutuhkan (assignment, argumen, return).</p><h3 id="contoh-execution" tabindex="-1">Contoh execution <a class="header-anchor" href="#contoh-execution" aria-label="Permalink to &quot;Contoh execution&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>score = 83</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(score &gt;= 60 ? &quot;lulus&quot; : &quot;remedial&quot;)</span></span>
<span class="line"><span>// lulus</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nilai = score &gt;= 90 | &quot;A&quot; | score &gt;= 80 | &quot;B&quot; | &quot;C&quot;</span></span>
<span class="line"><span>print(nilai)</span></span>
<span class="line"><span>// B</span></span>
<span class="line"><span></span></span>
<span class="line"><span>label = score &gt;= 90 -&gt; &quot;A&quot; | score &gt;= 80 -&gt; &quot;B&quot; | &quot;C&quot;</span></span>
<span class="line"><span>print(label)</span></span>
<span class="line"><span>// B</span></span></code></pre></div><p>Ternary juga sah sebagai argumen pemanggilan:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show(score &gt;= 60 ? &quot;LULUS&quot; : &quot;REMEDIAL&quot;)</span></span></code></pre></div>`,18)])])}const g=n(i,[["render",p]]);export{h as __pageData,g as default};
